#!/bin/bash
# Fieldbook — default settings.
# Do not edit this file. Your personal settings live in config.local.sh
# (created by setup / the library picker) and override anything here.

FIELDBOOK_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

# Where the knowledge library (ZIM files) lives.
# Point this at an external SSD in config.local.sh, e.g.:
#   LIBRARY_DIR="/Volumes/MySSD/fieldbook-library"
LIBRARY_DIR="$FIELDBOOK_DIR/library"

# Local AI model (set automatically by setup.sh based on your RAM).
FIELDBOOK_MODEL="qwen3:8b"

# Ports (change only if something else on your Mac uses them).
KIWIX_PORT=8090   # the raw library browser
APP_PORT=8900     # the Fieldbook dashboard + chat

# Load personal overrides.
[ -f "$FIELDBOOK_DIR/config.local.sh" ] && source "$FIELDBOOK_DIR/config.local.sh"

# Ollama binary: system install if present, otherwise the copy setup.sh
# downloads into bin/.
if command -v ollama >/dev/null 2>&1; then
  OLLAMA_BIN="$(command -v ollama)"
else
  OLLAMA_BIN="$FIELDBOOK_DIR/bin/ollama"
fi

export FIELDBOOK_DIR LIBRARY_DIR FIELDBOOK_MODEL KIWIX_PORT APP_PORT OLLAMA_BIN
